import type { MetadataRoute } from "next";

export default function manifest(): MetadataRoute.Manifest {
  return {
    // A stable id so the installed app keeps its identity across hosts (e.g. a dev tunnel).
    id: "/",
    name: "Space Works Events",
    short_name: "SW Events",
    description: "Create, manage, register for, and check in to free community events.",
    start_url: "/dashboard",
    scope: "/",
    display: "standalone",
    background_color: "#FFF4E8",
    theme_color: "#006E63",
    // Space Works app icon (public/brand, generated by scripts/generate-brand-assets.ts).
    icons: [
      { src: "/brand/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/brand/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
      { src: "/brand/maskable-192.png", sizes: "192x192", type: "image/png", purpose: "maskable" },
      { src: "/brand/maskable-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
    ],
  };
}
